package com.bank.ccr.service; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.web.client.RestClient; import java.util.*; @Service public class RagService { private final RestClient http=RestClient.create(); @Value("${app.rag.mode:mock}") String mode; @Value("${app.rag.base-url:http://localhost:8090}") String baseUrl; public List<String> retrieve(String q){ if(!"enterprise".equalsIgnoreCase(mode)) return List.of("CCR methodology: official exposure values come from validated risk engines; GenAI provides explanation only."); try { Map body=http.post().uri(baseUrl+"/retrieve").body(Map.of("query",q,"domain","CCR")).retrieve().body(Map.class); Object x=body==null?null:body.get("passages"); return x instanceof List<?> l?l.stream().map(String::valueOf).toList():List.of(); } catch(Exception e){ return List.of("Enterprise RAG unavailable; no unverified knowledge was added."); }} }
